'use client';
import { useEffect, useMemo, useRef, useState } from 'react';
import { ArrowRight, ArrowUpRight, ArrowLeft, BookOpen, Bookmark, Check, CheckCircle2, ChevronRight, Clock3, CloudCheck, Download, Feather, FileText, Flame, GraduationCap, LayoutDashboard, Leaf, Lightbulb, LockKeyhole, Menu, MessageSquareText, MoreHorizontal, Pause, PencilLine, Play, Plus, RotateCcw, Search, Settings2, ShieldCheck, Sparkles, Target, Timer, TrendingUp, Upload, X } from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import { categories, lessons, prompts, stages, warmups } from '@/lib/course';
import { analyze, wordsOf } from '@/lib/review';
import { safeBackup } from '@/lib/workspace';
import { useWorkspace } from '@/lib/use-workspace';
import type { Attempt, Draft, Lesson, Prompt, Workspace } from '@/lib/types';

type View='overview'|'learn'|'prompts'|'studio'|'progress'|'drafts'|'settings';
const navigation:{id:View;label:string;icon:LucideIcon}[]=[{id:'overview',label:'My dashboard',icon:LayoutDashboard},{id:'learn',label:'Learning path',icon:BookOpen},{id:'prompts',label:'Prompt library',icon:Lightbulb},{id:'studio',label:'Writing studio',icon:PencilLine},{id:'progress',label:'My progress',icon:TrendingUp},{id:'drafts',label:'My drafts',icon:FileText}];
const stamp=()=>new Date().toISOString();
const uid=()=>crypto.randomUUID();
const niceDate=(date:string)=>new Date(date).toLocaleDateString(undefined,{month:'short',day:'numeric'});
function download(name:string,data:string,type='text/plain'){const blob=new Blob([data],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
const prettyTitle=(view:View)=>navigation.find(n=>n.id===view)?.label||'Studio settings';
function IconButton({icon:Icon,label,onClick}:{icon:LucideIcon;label:string;onClick:()=>void}){return <button className="icon-button" title={label} aria-label={label} onClick={onClick}><Icon size={18}/></button>;}
function Pill({children,className=''}:{children:React.ReactNode;className?:string}){return <span className={`pill ${className}`}>{children}</span>;}
function Button({children,onClick,secondary=false,disabled=false,className=''}:{children:React.ReactNode;onClick:()=>void;secondary?:boolean;disabled?:boolean;className?:string}){return <button className={`${secondary?'button secondary':'button'} ${className}`} onClick={onClick} disabled={disabled}>{children}</button>;}

export default function Studio({userId,displayName}:{userId:string|null;displayName:string}){
 const {workspace:w,ready,status,error,update,retry,dismissError}=useWorkspace(userId);
 const [view,setView]=useState<View>('overview'),[mobile,setMobile]=useState(false),[selectedLesson,setSelectedLesson]=useState<string|null>(null),[activeDraft,setActiveDraft]=useState<string|null>(null),[selectedAttempt,setSelectedAttempt]=useState<string|null>(null),[toast,setToast]=useState(''),[modal,setModal]=useState<'warmup'|'custom'|'guide'|null>(null);
 const [quizPasses,setQuizPasses]=useState<Record<string,boolean>>({});
 const toastTimer=useRef<ReturnType<typeof setTimeout>|null>(null);
 function notify(message:string){setToast(message);if(toastTimer.current)clearTimeout(toastTimer.current);toastTimer.current=setTimeout(()=>setToast(''),4500);}
 function go(next:View){setView(next);setMobile(false);history.replaceState(null,'',`#${next}`);window.scrollTo({top:0,behavior:'instant'});}
 useEffect(()=>{const hash=location.hash.slice(1) as View;if([...navigation.map(n=>n.id),'settings'].includes(hash))setView(hash);const change=()=>{const value=location.hash.slice(1) as View;if([...navigation.map(n=>n.id),'settings'].includes(value))setView(value);};window.addEventListener('hashchange',change);return()=>window.removeEventListener('hashchange',change);},[]);
 useEffect(()=>{if(!ready)return;try{const saved=sessionStorage.getItem('write-again-active');if(saved&&w.drafts.some(d=>d.id===saved))setActiveDraft(saved);}catch{}},[ready]);
 useEffect(()=>{if(activeDraft)try{sessionStorage.setItem('write-again-active',activeDraft);}catch{}},[activeDraft]);
 const completed=new Set(w.completions.map(c=>c.lessonId));
 const stageOpen=(stage:number)=>lessons.filter(l=>l.stage<stage).every(l=>completed.has(l.id));
 const nextLesson=lessons.find(l=>!completed.has(l.id))||lessons[15];
 const currentStage=Math.min(3,Math.floor(w.completions.length/4));
 const totalWords=w.drafts.reduce((sum,d)=>sum+wordsOf(d.text).length,0);
 const average=w.attempts.length?Math.round(w.attempts.reduce((s,a)=>s+a.review.score,0)/w.attempts.length):null;
 const days=new Set(w.attempts.map(a=>new Date(a.createdAt).toLocaleDateString('en-CA')));
 let streak=0;const day=new Date();if(!days.has(day.toLocaleDateString('en-CA')))day.setDate(day.getDate()-1);while(days.has(day.toLocaleDateString('en-CA'))){streak++;day.setDate(day.getDate()-1);}
 const xp=w.completions.length*100+new Set(w.attempts.map(a=>a.draftId)).size*25;
 const active=w.drafts.find(d=>d.id===activeDraft)||null;
 function openLesson(lesson:Lesson){if(!stageOpen(lesson.stage)){notify('Complete the previous stage to unlock this lesson. The prompt library is always open.');return;}setSelectedLesson(lesson.id);go('learn');}
 function startPrompt(prompt:Prompt,lesson?:Lesson){
  if(w.drafts.length>=200){notify('Your archive has reached 200 drafts. Export a backup before starting another.');return;}
  const existing=lesson?w.drafts.find(d=>d.prompt.lessonId===lesson.id):null;
  if(existing){setActiveDraft(existing.id);setSelectedAttempt(null);go('studio');return;}
  const now=stamp(),draft:Draft={id:uid(),title:prompt.title,prompt,text:'',outline:['','',''],createdAt:now,updatedAt:now,completedChecks:lesson&&quizPasses[lesson.id]?[`quiz:${lesson.id}`]:[]};
  update(s=>({...s,drafts:[draft,...s.drafts]}));setActiveDraft(draft.id);setSelectedAttempt(null);go('studio');
 }
 function changeDraft(fn:(d:Draft)=>Draft){if(!active)return;update(s=>({...s,drafts:s.drafts.map(d=>d.id===active.id?{...fn(d),updatedAt:stamp()}:d)}));}
 function reviewDraft(){if(!active)return;if(wordsOf(active.text).length<20){notify('Write at least 20 words to get useful feedback. You can save any length.');return;}if(w.attempts.length>=600){notify('Review archive is full. Export a backup before adding another review.');return;}
  const last=w.attempts.find(a=>a.draftId===active.id&&a.text===active.text&&a.review.tone===w.settings.tone);if(last){setSelectedAttempt(last.id);notify('Showing the saved review of this exact draft.');return;}
  const now=stamp(),attempt:Attempt={id:uid(),draftId:active.id,text:active.text,title:active.title,prompt:active.prompt,review:analyze(active.text,active.prompt,w.settings.tone),createdAt:now,updatedAt:now,reflection:''};update(s=>({...s,attempts:[attempt,...s.attempts]}));setSelectedAttempt(attempt.id);notify('Review saved. Choose one priority and revise.');
 }
 function bookmark(id:string){update(s=>({...s,bookmarks:s.bookmarks.includes(id)?s.bookmarks.filter(b=>b!==id):[...s.bookmarks,id],settingsUpdatedAt:stamp()}));}
 function exportBackup(){download(`write-again-backup-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify({app:'Write Again',exportedAt:stamp(),workspace:w},null,2),'application/json');notify('Backup downloaded. Keep it somewhere safe.');}
 function finishLesson(lesson:Lesson,attempt:Attempt){
  if(!active||attempt.text!==active.text||wordsOf(active.text).length<lesson.prompt.minWords||wordsOf(active.text).length>lesson.prompt.maxWords||attempt.review.score<stages[lesson.stage].threshold||!active.completedChecks.includes(`quiz:${lesson.id}`)||!lesson.checklist.every(c=>active.completedChecks.includes(c))){notify('Finish the check, meet the practice range and score, then complete your self-review.');return;}
  update(s=>({...s,completions:[...s.completions.filter(c=>c.lessonId!==lesson.id),{lessonId:lesson.id,attemptId:attempt.id,completedAt:stamp()}]}));notify('Lesson complete. Your next step is ready.');setSelectedLesson(null);go('learn');
 }
 const latestAttempt=selectedAttempt?w.attempts.find(a=>a.id===selectedAttempt&&a.draftId===active?.id):w.attempts.find(a=>a.draftId===active?.id);
 return <div className="app-shell">
  <a className="skip-link" href="#main">Skip to content</a>
  {mobile&&<button className="nav-scrim" aria-label="Close navigation" onClick={()=>setMobile(false)}/>}
  <aside className={`sidebar ${mobile?'open':''}`}>
   <button className="brand" onClick={()=>go('overview')} aria-label="Write Again home"><span className="brand-symbol"><Feather size={23}/></span><span>write<span className="brand-serif">again.</span><small>A LITTLE BETTER, EVERY DRAFT</small></span></button>
   <div className="nav-section-label">YOUR WRITING SPACE</div>
   <nav aria-label="Main navigation">{navigation.map(({id,label,icon:Icon})=><button key={id} className={`nav-item ${view===id?'active':''}`} aria-current={view===id?'page':undefined} onClick={()=>{if(id==='learn')setSelectedLesson(null);go(id);}}><Icon size={19}/><span>{label}</span>{id==='drafts'&&w.drafts.length>0&&<span className="nav-count">{w.drafts.length}</span>}{id==='overview'&&<span className="active-dot"/>}</button>)}</nav>
   <div className="sidebar-bottom"><div className="side-note"><Leaf size={21}/><p>Good writing starts<br/>with showing up.</p><button onClick={()=>setModal('warmup')}>Just 5 minutes today <ArrowUpRight size={13}/></button></div><button className={`nav-item ${view==='settings'?'active':''}`} onClick={()=>go('settings')}><Settings2 size={18}/> Studio settings</button><div className="profile"><span className="avatar">{displayName.slice(0,1).toUpperCase()}</span><span><strong>{displayName}</strong><small>Your personal writing space</small></span><ShieldCheck size={16}/></div></div>
  </aside>
  <div className="main-shell"><header className="topbar"><div className="breadcrumbs"><button className="mobile-menu" aria-label="Open navigation" onClick={()=>setMobile(true)}><Menu size={21}/></button><span>My workspace</span><ChevronRight size={13}/><strong>{prettyTitle(view)}</strong></div><div className="topbar-right"><span className="save-state" title={status}><CloudCheck size={15}/><span>{status}</span></span><span className="private-label"><LockKeyhole size={12}/> LOCAL SAVING</span><span className="avatar small">{displayName.slice(0,1).toUpperCase()}</span></div></header>
   <main id="main" tabIndex={-1}>
    {error&&<div className="notice" role="status"><span>{error}</span><button onClick={retry}>Retry save</button><IconButton icon={X} label="Dismiss notice" onClick={dismissError}/></div>}
    {!userId&&<div className="notice"><span>No account needed. Your drafts and progress are saved in this browser. Export a backup to keep a separate copy.</span><button onClick={()=>go('settings')}>Backup settings</button></div>}
    {!ready?<div className="loading-state"><Feather size={30}/><h1>Opening your writing space…</h1><p>Your saved drafts will be here shortly.</p></div>:<>
     {view==='overview'&&<><div className="page-heading"><div><div className="eyebrow">A FRESH PAGE, A FRESH START</div><h1>Welcome to your next chapter<span className="sage">.</span></h1><p>Your voice is still there. Let’s put it back on the page.</p></div><Button secondary onClick={()=>setModal('warmup')}><Sparkles size={16}/> Beat the blank page</Button></div>
      <section className="hero-card"><div className="hero-copy"><Pill><span className="tiny-dot"/> YOUR COMEBACK STARTS HERE</Pill><h2>You don’t need perfect words.<br/>You just need <em>the next one.</em></h2><p>A little practice. Honest feedback. One stronger draft at a time.<br className="desktop-only"/>Build your confidence from the first paragraph to your personal statement.</p><div className="hero-actions"><Button onClick={()=>openLesson(nextLesson)}>{w.completions.length?'Continue my learning':'Start my writing journey'} <ArrowRight size={16}/></Button><button className="text-button" onClick={()=>setModal('custom')}>Or, write freely <ArrowUpRight size={15}/></button></div><div className="hero-foot"><span><Check size={13}/> Your pace</span><span><Check size={13}/> Honest feedback</span><span><Check size={13}/> Every draft counts</span></div></div><div className="hero-art" aria-hidden="true"><span className="art-orbit orbit-one"/><span className="art-orbit orbit-two"/><div className="paper paper-back"/><div className="paper paper-front"><div className="paper-label">A WORK IN PROGRESS</div><div className="paper-title">Dear blank page,</div><div className="paper-line long"/><div className="paper-line"/><div className="paper-line long"/><div className="paper-line short"/><span className="paper-scribble">let’s begin again.</span><Feather size={48} strokeWidth={1}/></div><span className="art-spark">✳</span><div className="art-caption"><span className="tiny-dot"/> A LITTLE BRAVER. A LITTLE BETTER.</div></div></section>
      <div className="stats-grid"><Stat icon={BookOpen} label="Lessons completed" value={`${w.completions.length}`} suffix="/ 16" note={w.completions.length?'Small steps, real momentum':'Your first step is waiting'}/><Stat icon={PencilLine} label="Pieces practiced" value={`${new Set(w.attempts.map(a=>a.draftId)).size}`} note={`${totalWords.toLocaleString()} words on the page`}/><Stat icon={Target} label="Average rubric estimate" value={average===null?'—':`${average}`} suffix={average===null?'':'/ 100'} note={average===null?'Write a piece to set your baseline':'Practice signal, not an official grade'}/><Stat icon={Flame} label="Practice streak" value={`${streak}`} suffix={streak===1?'day':'days'} note={streak?'Keep your own rhythm':'A fresh start counts, too'}/></div>
      <div className="dashboard-columns"><section className="card learning-preview"><div className="section-top"><div><span className="eyebrow">ONE STEP AT A TIME</span><h2>Your learning path</h2></div><button className="text-button" onClick={()=>{setSelectedLesson(null);go('learn');}}>View full path <ArrowUpRight size={15}/></button></div><div className="stage-stepper">{stages.map((s,i)=><div key={s.name} className={`${i===currentStage?'current':''} ${stageOpen(i)?'available':''}`}><span className="stage-circle">{lessons.filter(l=>l.stage===i).every(l=>completed.has(l.id))?<Check size={14}/>:String(i+1).padStart(2,'0')}</span><span>{s.level}</span></div>)}</div><div className="next-lesson"><div className="next-lesson-icon"><BookOpen size={25} strokeWidth={1.5}/></div><div><span className="eyebrow">STAGE {currentStage+1} · {stages[currentStage].name.toUpperCase()}</span><h3>{nextLesson.title}</h3><p>{nextLesson.subtitle}</p><div className="lesson-meta"><span><Clock3 size={13}/> {nextLesson.minutes} min lesson</span><span>+ a short writing exercise</span></div></div></div><div className="path-bottom"><span>{w.completions.length} of 16 lessons complete</span><strong>{Math.round(w.completions.length/16*100)}%</strong></div><div className="progress-track"><span style={{width:`${w.completions.length/16*100}%`}}/></div><Button secondary className="full-width" onClick={()=>openLesson(nextLesson)}>{w.completions.length?'Continue lesson':'Begin lesson 01'}<ArrowRight size={15}/></Button></section>
       <section className="daily-prompt"><div className="section-top"><span className="eyebrow">TODAY’S SMALL CHALLENGE</span><span className="mini-icon"><Lightbulb size={18}/></span></div><Pill>PERSONAL REFLECTION</Pill><h2>{prompts[0].title}</h2><p>{prompts[0].question}</p><div className="lesson-meta"><span><Clock3 size={14}/> {prompts[0].minutes} min</span><span>{prompts[0].minWords}–{prompts[0].maxWords} words</span></div><Button onClick={()=>startPrompt(prompts[0])}>Give this a try <ArrowUpRight size={16}/></Button><small>One honest paragraph is a good place to start.</small></section></div>
      <div className="section-top lower-heading"><div><span className="eyebrow">MORE WAYS TO GET MOVING</span><h2>Make room for your words</h2></div></div><div className="quick-grid"><Quick icon={Timer} title="A five-minute warm-up" text="Quiet the inner editor. Just get the words moving." onClick={()=>setModal('warmup')}/><Quick icon={GraduationCap} title="Admissions, in your voice" text="Go beyond achievements. Tell a story that is yours." onClick={()=>{go('prompts');sessionStorage.setItem('write-again-filter','Admissions');}}/><Quick icon={MessageSquareText} title="Criticism you can use" text="See the rubric, understand the limits, and revise." onClick={()=>setModal('guide')}/></div><div className="dashboard-footer"><Feather size={14}/><span>Progress is a collection of imperfect pages.</span><span className="footer-end">{prompts.length} prompts · 16 lessons · Your own pace</span></div></>}
     {view==='learn'&&(selectedLesson?<LessonDetail lesson={lessons.find(l=>l.id===selectedLesson)!} completed={completed.has(selectedLesson)} existing={w.drafts.find(d=>d.prompt.lessonId===selectedLesson)} passed={!!quizPasses[selectedLesson]} onBack={()=>setSelectedLesson(null)} onPass={()=>{setQuizPasses(s=>({...s,[selectedLesson]:true}));update(s=>({...s,drafts:s.drafts.map(d=>d.prompt.lessonId===selectedLesson?{...d,completedChecks:[...new Set([...d.completedChecks,`quiz:${selectedLesson}`])],updatedAt:stamp()}:d)}));}} onStart={()=>startPrompt(lessons.find(l=>l.id===selectedLesson)!.prompt,lessons.find(l=>l.id===selectedLesson))}/>:<><PageHeading kicker="FROM BLANK PAGE TO YOUR OWN VOICE" title="Your learning path" text="Read. Try. Revise. Build a habit you can carry into every essay."/><div className="course-summary"><div><strong>{w.completions.length} <span>/ 16 lessons</span></strong><p>Each stage unlocks when its four lessons are complete.</p></div><div className="course-summary-progress"><span>{Math.round(w.completions.length/16*100)}% of your path</span><div className="progress-track"><span style={{width:`${w.completions.length/16*100}%`}}/></div></div></div>{stages.map((s,i)=><section className={`course-stage ${stageOpen(i)?'':'locked'}`} key={s.name}><div className="stage-heading"><span className="stage-number" style={{background:s.color}}>{String(i+1).padStart(2,'0')}</span><div><Pill>{s.level}</Pill><h2>{s.name}</h2><p>{s.description}</p></div><span className="stage-count">{stageOpen(i)?`${lessons.filter(l=>l.stage===i&&completed.has(l.id)).length}/4 complete`:<><LockKeyhole size={14}/> Complete stage {i}</>}</span></div><div className="course-lesson-list">{lessons.filter(l=>l.stage===i).map(l=><button key={l.id} disabled={!stageOpen(i)} onClick={()=>openLesson(l)}><span className={`lesson-status ${completed.has(l.id)?'done':''}`}>{completed.has(l.id)?<Check size={18}/>:stageOpen(i)?<Play size={14}/>:<LockKeyhole size={14}/>}</span><span><strong>{l.title}</strong><small>{l.subtitle}</small></span><span className="lesson-time">{l.minutes} min <ChevronRight size={16}/></span></button>)}</div></section>)}<div className="tip-banner"><Lightbulb size={20}/><p><strong>Already comfortable with a later skill?</strong> Every level in the prompt library is available from the start. Course checkpoints track practice, not a certified assessment of mastery.</p><button onClick={()=>go('prompts')}>Browse prompts <ArrowUpRight size={15}/></button></div></>)}
     {view==='prompts'&&<PromptLibrary bookmarks={w.bookmarks} onBookmark={bookmark} onStart={startPrompt} onCustom={()=>setModal('custom')}/>}
     {view==='studio'&&(active?<WritingStudio key={active.id} draft={active} attempt={latestAttempt||null} attempts={w.attempts.filter(a=>a.draftId===active.id)} tone={w.settings.tone} dailyMinutes={w.settings.dailyMinutes} status={status} onChange={changeDraft} onReview={reviewDraft} onSelectReview={setSelectedAttempt} onBack={()=>go('drafts')} onFinish={finishLesson} onGoLesson={id=>openLesson(lessons.find(l=>l.id===id)!)} onReflect={(attemptId,reflection)=>update(s=>({...s,attempts:s.attempts.map(a=>a.id===attemptId?{...a,reflection,updatedAt:stamp()}:a)}))}/>:<><PageHeading kicker="THE PAGE IS YOURS" title="Your writing studio" text="Pick a starting point. Save a draft. Come back and make it stronger."/><div className="empty-studio"><span className="large-icon"><Feather size={37} strokeWidth={1}/></span><h2>One thought is enough to begin.</h2><p>Choose a practice prompt, bring your own essay, or spend five minutes writing without a score.</p><div className="button-row"><Button onClick={()=>go('prompts')}>Find a prompt <ArrowRight size={15}/></Button><Button secondary onClick={()=>setModal('custom')}>Bring my own topic</Button></div><button className="text-button" onClick={()=>setModal('warmup')}><Sparkles size={15}/> I’m feeling blocked</button></div>{w.drafts.length>0&&<DraftList drafts={w.drafts.slice(0,4)} attempts={w.attempts} onOpen={d=>{setActiveDraft(d.id);setSelectedAttempt(null);}}/>}</>)}
     {view==='drafts'&&<><PageHeading kicker="NOTHING YOU WRITE IS WASTED" title="Your drafts & revisions" text="Your writing stays here, including earlier versions and the feedback they received." action={<Button onClick={()=>setModal('custom')}><Plus size={16}/> New draft</Button>}/><DraftList drafts={w.drafts} attempts={w.attempts} onOpen={d=>{setActiveDraft(d.id);setSelectedAttempt(null);go('studio');}}/>{!w.drafts.length&&<Empty icon={FileText} title="Your first page is waiting" text="Start with a prompt or bring an essay you already want to improve." action={<Button onClick={()=>go('prompts')}>Explore prompts <ArrowRight size={15}/></Button>}/>}</>}
     {view==='progress'&&<Progress workspace={w} xp={xp} streak={streak} onOpen={attempt=>{setActiveDraft(attempt.draftId);setSelectedAttempt(attempt.id);go('studio');}} onPractice={()=>go('prompts')}/>}
     {view==='settings'&&<Settings workspace={w} onUpdate={update} onExport={exportBackup} onNotify={notify}/>}
    </>}
   </main>
  </div>
  {toast&&<div className="toast" role="status"><CheckCircle2 size={17}/>{toast}<button aria-label="Dismiss notification" onClick={()=>setToast('')}><X size={14}/></button></div>}
  {modal&&<Modal title={modal==='warmup'?'Let’s loosen the words.':modal==='custom'?'A page for your own idea.':'Feedback that helps you revise.'} onClose={()=>setModal(null)}>{modal==='warmup'?<Warmup storageKey={`write-again-warmup:${userId||'local'}`} onSave={(text,title)=>{const now=stamp(),draft:Draft={id:uid(),title,prompt:{id:`warmup-${uid()}`,title,question:'Develop one thought from this freewrite into a focused reflection. Use a particular moment and explain why it matters.',category:'Personal growth',level:1,minWords:80,maxWords:200,minutes:5,hints:['Choose one living sentence.','Add a concrete moment.','Explain why it matters.'],kind:'micro'},text,outline:['','',''],createdAt:now,updatedAt:now,completedChecks:[]};update(s=>({...s,drafts:[draft,...s.drafts]}));setActiveDraft(draft.id);setSelectedAttempt(null);setModal(null);go('studio');notify('Warm-up saved as a draft. Keep the part that feels alive.');}}/>:modal==='custom'?<CustomPrompt onStart={p=>{setModal(null);startPrompt(p);}}/>:<FeedbackGuide onClose={()=>setModal(null)}/>}</Modal>}
 </div>;
}

function PageHeading({kicker,title,text,action}:{kicker:string;title:string;text:string;action?:React.ReactNode}){return <div className="page-heading"><div><div className="eyebrow">{kicker}</div><h1>{title}<span className="sage">.</span></h1><p>{text}</p></div>{action}</div>;}
function Stat({icon:Icon,label,value,suffix,note}:{icon:LucideIcon;label:string;value:string;suffix?:string;note:string}){return <div className="stat-card"><div className="stat-label"><span>{label}</span><Icon size={17}/></div><div className="stat-number">{value} <small>{suffix}</small></div><p>{note}</p></div>;}
function Quick({icon:Icon,title,text,onClick}:{icon:LucideIcon;title:string;text:string;onClick:()=>void}){return <button className="quick-card" onClick={onClick}><span className="quick-icon"><Icon size={22} strokeWidth={1.5}/></span><span><strong>{title}</strong><small>{text}</small></span><ArrowUpRight size={17}/></button>;}
function Empty({icon:Icon,title,text,action}:{icon:LucideIcon;title:string;text:string;action?:React.ReactNode}){return <div className="empty"><Icon size={30} strokeWidth={1.3}/><h2>{title}</h2><p>{text}</p>{action}</div>;}

function LessonDetail({lesson:l,completed,existing,passed,onBack,onPass,onStart}:{lesson:Lesson;completed:boolean;existing?:Draft;passed:boolean;onBack:()=>void;onPass:()=>void;onStart:()=>void}){
 const [answer,setAnswer]=useState<number|null>(null),[checked,setChecked]=useState(false);const correct=passed||existing?.completedChecks.includes(`quiz:${l.id}`)||checked&&answer===l.check.answer;
 return <div className="lesson-detail" key={l.id}><button className="text-button back-link" onClick={onBack}><ArrowLeft size={15}/> Back to your learning path</button><div className="lesson-header"><div className="eyebrow">STAGE {l.stage+1} · LESSON {lessons.indexOf(l)+1} OF 16</div><h1>{l.title}<span className="sage">.</span></h1><p>{l.subtitle}</p><div className="lesson-meta"><Pill>{stages[l.stage].level}</Pill><span><Clock3 size={14}/> {l.minutes} min read</span>{completed&&<Pill className="green"><Check size={12}/> Completed</Pill>}</div></div><div className="lesson-layout"><article className="lesson-article">{l.sections.map((s,i)=><section key={s.title}><span className="lesson-section-num">0{i+1}</span><h2>{s.title}</h2><p>{s.body}</p></section>)}<section className="example-section"><div className="eyebrow">SEE THE DIFFERENCE</div><div className="example before"><span>FIRST THOUGHT</span><p>{l.before}</p></div><div className="example after"><span>A MORE DELIBERATE DRAFT</span><p>{l.after}</p></div><p className="example-why"><Lightbulb size={17}/>{l.why}</p></section><section className="knowledge-check"><div className="eyebrow">A QUICK CHECK</div><h2>{l.check.question}</h2><div className="quiz-options">{l.check.options.map((option,i)=><button className={`${answer===i?'selected':''} ${correct&&i===l.check.answer?'correct':''}`} onClick={()=>{setAnswer(i);setChecked(false);}} key={option}><span>{String.fromCharCode(65+i)}</span>{option}{correct&&i===l.check.answer&&<Check size={16}/>}</button>)}</div>{!correct&&<Button secondary disabled={answer===null} onClick={()=>{setChecked(true);if(answer===l.check.answer)onPass();}}>Check my understanding <ArrowRight size={15}/></Button>}{checked&&!correct&&<p className="check-wrong" role="status">Not quite. Read the example again and consider what makes the writing clearer. Try another answer.</p>}{correct&&<div className="check-correct" role="status"><CheckCircle2 size={18}/><p><strong>You’ve got the idea.</strong> {l.check.explanation}</p></div>}</section></article><aside className="lesson-practice card"><span className="mini-icon"><PencilLine size={20}/></span><div className="eyebrow">MAKE IT STICK</div><h2>Your writing task</h2><p>{l.prompt.question}</p><div className="lesson-meta"><span>{l.prompt.minWords}–{l.prompt.maxWords} words</span><span>{l.prompt.minutes} min</span></div><div className="checkpoint"><strong>To complete this lesson</strong><ul><li>Pass the quick check.</li><li>Write within the practice range.</li><li>Reach a rubric estimate of {stages[l.stage].threshold}+.</li><li>Review your draft against the three lesson checks.</li></ul></div><Button className="full-width" disabled={!correct} onClick={onStart}>{existing?'Return to my draft':'Start the writing task'}<ArrowRight size={15}/></Button>{!correct&&<small>Pass the quick check to open this task.</small>}<small>These are practice checkpoints. You decide whether you have applied the lesson honestly.</small></aside></div></div>;
}

function PromptLibrary({bookmarks,onBookmark,onStart,onCustom}:{bookmarks:string[];onBookmark:(id:string)=>void;onStart:(p:Prompt)=>void;onCustom:()=>void}){
 const [query,setQuery]=useState(''),[category,setCategory]=useState('All topics'),[level,setLevel]=useState('All levels'),[savedOnly,setSavedOnly]=useState(false);
 useEffect(()=>{try{const filter=sessionStorage.getItem('write-again-filter');if(filter){setCategory(filter);sessionStorage.removeItem('write-again-filter');}}catch{}},[]);
 const filtered=prompts.filter(p=>(category==='All topics'||p.category===category)&&(level==='All levels'||p.level===Number(level))&&(!savedOnly||bookmarks.includes(p.id))&&`${p.title} ${p.question} ${p.category}`.toLowerCase().includes(query.toLowerCase()));
 return <><PageHeading kicker="THERE IS ALWAYS SOMETHING WORTH EXPLORING" title="Find your next idea" text="64 original prompts across eight topics. From a small paragraph to a full personal statement." action={<Button secondary onClick={onCustom}><Plus size={16}/> My own topic</Button>}/><div className="library-toolbar"><label className="search-field"><Search size={17}/><input aria-label="Search prompts" placeholder="Search for an idea, topic, or feeling…" value={query} onChange={e=>setQuery(e.target.value)}/></label><label className="sr-only" htmlFor="level">Difficulty</label><select id="level" value={level} onChange={e=>setLevel(e.target.value)}><option>All levels</option>{stages.map((s,i)=><option key={s.name} value={i+1}>{s.level}</option>)}</select><button className={`filter-bookmarks ${savedOnly?'selected':''}`} onClick={()=>setSavedOnly(!savedOnly)}><Bookmark size={16} fill={savedOnly?'currentColor':'none'}/> Saved ({bookmarks.length})</button><Button secondary disabled={!filtered.length} onClick={()=>onStart(filtered[Math.floor(Math.random()*filtered.length)])}><Sparkles size={15}/> Surprise me</Button></div><div className="topic-chips">{['All topics',...categories].map(c=><button key={c} className={category===c?'active':''} onClick={()=>setCategory(c)}>{c}</button>)}</div><div className="result-count">{filtered.length} {filtered.length===1?'prompt':'prompts'} to explore <span>All levels are available at your own pace.</span></div><div className="prompt-grid">{filtered.map(p=><article className="prompt-card" key={p.id}><div className="section-top"><span className="eyebrow">{p.category.toUpperCase()}</span><button className={`icon-button ${bookmarks.includes(p.id)?'bookmarked':''}`} aria-label={`${bookmarks.includes(p.id)?'Unsave':'Save'} ${p.title}`} onClick={()=>onBookmark(p.id)}><Bookmark size={17} fill={bookmarks.includes(p.id)?'currentColor':'none'}/></button></div><h2>{p.title}</h2><p>{p.question}</p><div className="prompt-card-bottom"><div><Pill>{stages[p.level-1].level}</Pill><span>{p.minWords}–{p.maxWords} words · {p.minutes} min</span></div><button aria-label={`Write about ${p.title}`} onClick={()=>onStart(p)}><ArrowUpRight size={19}/></button></div></article>)}</div>{!filtered.length&&<Empty icon={Search} title="No prompts in this corner yet" text="Try another topic, clear the search, or turn off the saved-only filter."/>}<div className="tip-banner"><GraduationCap size={21}/><p>Admissions prompts here are original practice questions. Always follow the current instructions and word limits of the institution you apply to.</p></div></>;
}

function Countdown({minutes=15}:{minutes?:number}){
 const [duration,setDuration]=useState(minutes),[remaining,setRemaining]=useState(minutes*60),[endsAt,setEndsAt]=useState<number|null>(null),[finished,setFinished]=useState(false);
 useEffect(()=>{if(endsAt===null)return;function tick(){const left=Math.max(0,Math.ceil((endsAt!-Date.now())/1000));setRemaining(left);if(left<=0){setEndsAt(null);setFinished(true);}}tick();const interval=setInterval(tick,300);return()=>clearInterval(interval);},[endsAt]);
 return <div className="timer-widget"><div className="timer-controls"><Timer size={16}/><span className="timer-display" aria-label={`${Math.floor(remaining/60)} minutes ${remaining%60} seconds`}>{String(Math.floor(remaining/60)).padStart(2,'0')}:{String(remaining%60).padStart(2,'0')}</span><label className="sr-only" htmlFor="timer-duration">Focus duration</label><select id="timer-duration" value={duration} disabled={endsAt!==null} onChange={e=>{const n=Number(e.target.value);setDuration(n);setRemaining(n*60);setFinished(false);}}>{[...new Set([5,8,10,15,20,25,30,35,45,60,minutes])].sort((a,b)=>a-b).map(n=><option key={n} value={n}>{n} min</option>)}</select><IconButton icon={endsAt!==null?Pause:Play} label={endsAt!==null?'Pause focus timer':'Start focus timer'} onClick={()=>{if(endsAt!==null){setRemaining(Math.max(0,Math.ceil((endsAt-Date.now())/1000)));setEndsAt(null);}else{const left=remaining||duration*60;setRemaining(left);setFinished(false);setEndsAt(Date.now()+left*1000);}}}/><IconButton icon={RotateCcw} label="Reset focus timer" onClick={()=>{setEndsAt(null);setRemaining(duration*60);setFinished(false);}}/></div>{finished&&<small role="status">Time’s up. Finish your thought; your draft stays editable.</small>}</div>;
}

function WritingStudio({draft:d,attempt,attempts,tone,dailyMinutes,status,onChange,onReview,onSelectReview,onBack,onFinish,onGoLesson,onReflect}:{draft:Draft;attempt:Attempt|null;attempts:Attempt[];tone:'direct'|'gentle';dailyMinutes:number;status:string;onChange:(fn:(d:Draft)=>Draft)=>void;onReview:()=>void;onSelectReview:(id:string)=>void;onBack:()=>void;onFinish:(l:Lesson,a:Attempt)=>void;onGoLesson:(id:string)=>void;onReflect:(id:string,text:string)=>void}){
 const [focus,setFocus]=useState(false),[plan,setPlan]=useState(false),[tab,setTab]=useState<'feedback'|'history'>('feedback');
 const wordCount=wordsOf(d.text).length,lesson=lessons.find(l=>l.id===d.prompt.lessonId),current=attempt?.text===d.text,threshold=lesson?stages[lesson.stage].threshold:0;
 const canComplete=!!lesson&&!!attempt&&current&&wordCount>=d.prompt.minWords&&wordCount<=d.prompt.maxWords&&attempt.review.score>=threshold&&d.completedChecks.includes(`quiz:${lesson.id}`)&&lesson.checklist.every(c=>d.completedChecks.includes(c));
 function exportEssay(){download(`${d.title.replace(/[^a-z0-9]+/gi,'-').slice(0,80)||'my-essay'}.txt`,`${d.title}\n\nPrompt: ${d.prompt.question}\n\n${d.text}`);}
 const previous=attempt?attempts.filter(a=>a.createdAt<attempt.createdAt).sort((a,b)=>b.createdAt.localeCompare(a.createdAt))[0]:null;
 return <div className={`studio-page ${focus?'focus-mode':''}`}><div className="editor-top"><button className="text-button" onClick={onBack}><ArrowLeft size={15}/> All my drafts</button><div className="button-row"><button className="text-button" onClick={()=>setFocus(!focus)}><Target size={15}/>{focus?'Exit focus':'Focus mode'}</button><IconButton icon={Download} label="Download this essay" onClick={exportEssay}/></div></div><div className="writing-layout"><div className="writing-main"><div className="prompt-brief"><div className="section-top"><span className="eyebrow">YOUR PRACTICE PROMPT</span><Pill>{stages[d.prompt.level-1].level}</Pill></div><h2>{d.prompt.title}</h2><p>{d.prompt.question}</p><div className="brief-bottom"><span>{d.prompt.minWords}–{d.prompt.maxWords} words · {d.prompt.category}</span>{lesson&&<button className="text-button" onClick={()=>onGoLesson(lesson.id)}>Read lesson <ArrowUpRight size={14}/></button>}</div><details><summary>Need a nudge?</summary><ul>{d.prompt.hints.map(h=><li key={h}>{h}</li>)}</ul></details></div><div className="editor-toolbar"><button className={`text-button ${plan?'sage':''}`} onClick={()=>setPlan(!plan)}><FileText size={15}/> {plan?'Hide outline':'Plan my response'}</button><Countdown minutes={Math.min(dailyMinutes,d.prompt.minutes)}/></div>{plan&&<div className="outline-panel"><div className="eyebrow">A SMALL PLAN, NOT A CAGE</div>{['The point or moment I want to explore','My strongest example or supporting detail','What the reader should understand by the end'].map((label,i)=><label key={label}>{i+1}. {label}<textarea maxLength={3000} rows={2} value={d.outline[i]||''} placeholder="A rough note is enough…" onChange={e=>onChange(old=>({...old,outline:[0,1,2].map(n=>n===i?e.target.value:old.outline[n]||'')}))}/></label>)}</div>}<div className="essay-sheet"><label className="sr-only" htmlFor="essay-title">Essay title</label><input id="essay-title" className="essay-title" maxLength={500} value={d.title} onChange={e=>onChange(old=>({...old,title:e.target.value}))} placeholder="Give this draft a title…"/><label className="sr-only" htmlFor="essay-body">Your essay</label><textarea id="essay-body" className="essay-body" maxLength={60000} value={d.text} onChange={e=>onChange(old=>({...old,text:e.target.value}))} placeholder={'Start with what you notice. You can make it beautiful later.\n\nLeave a blank line between paragraphs.'} spellCheck autoCapitalize="sentences"/><div className="editor-bottom"><span className={wordCount>d.prompt.maxWords?'over-limit':''}>{wordCount} words <small>/ {d.prompt.minWords}–{d.prompt.maxWords} target</small></span><span><CloudCheck size={13}/>{status}</span></div></div><div className="review-actions"><p><ShieldCheck size={14}/> Your draft is saved as you write.</p><Button disabled={wordCount<20} onClick={()=>{setTab('feedback');onReview();}}>Get honest feedback <ArrowRight size={16}/></Button></div>{wordCount<20&&<p className="muted small-text">The reviewer needs at least 20 words. You can save a draft of any length.</p>}
 {lesson&&<section className="lesson-selfcheck card"><div className="eyebrow">APPLY THE LESSON</div><h2>Before you call it finished</h2><p>Check these only after inspecting your own draft.</p>{lesson.checklist.map(c=><label key={c}><input type="checkbox" checked={d.completedChecks.includes(c)} onChange={e=>onChange(old=>({...old,completedChecks:e.target.checked?[...old.completedChecks,c]:old.completedChecks.filter(x=>x!==c)}))}/>{c}</label>)}<div className="checkpoint-status"><span>{d.completedChecks.includes(`quiz:${lesson.id}`)?'✓ Quick check passed':'○ Pass the lesson’s quick check'}</span><span>{wordCount>=d.prompt.minWords&&wordCount<=d.prompt.maxWords?'✓ Word target met':'○ Meet the practice word range'}</span><span>{attempt&&current&&attempt.review.score>=threshold?`✓ ${threshold}+ rubric checkpoint met`:`○ Get a current review of ${threshold}+`}</span></div><Button disabled={!canComplete} onClick={()=>{if(attempt)onFinish(lesson,attempt);}}>Complete lesson <CheckCircle2 size={16}/></Button></section>}
 </div><aside className="feedback-panel"><div className="feedback-tabs"><button className={tab==='feedback'?'active':''} onClick={()=>setTab('feedback')}><MessageSquareText size={15}/> Feedback</button><button className={tab==='history'?'active':''} onClick={()=>setTab('history')}><Clock3 size={15}/> Versions ({attempts.length})</button></div>{tab==='feedback'?(attempt?<><ReviewPanel attempt={attempt} current={!!current} previous={previous||null}/><div className="revision-note"><label htmlFor="revision-note">My next revision</label><p>What will you change, and why should it help the reader?</p><textarea id="revision-note" maxLength={3000} rows={4} value={attempt.reflection} placeholder="I will revise… because…" onChange={e=>onReflect(attempt.id,e.target.value)}/></div></>:<div className="feedback-empty"><span className="large-icon"><MessageSquareText size={26} strokeWidth={1.3}/></span><h2>A useful second look</h2><p>Write a draft, then ask for a direct review. You’ll get an estimate across five rubric areas, quoted flags, and a practical next step.</p><Pill>{tone==='direct'?'Direct & demanding':'Calm & constructive'}</Pill><p className="small-text">Automated pattern feedback. It cannot judge originality, factual accuracy, the quality of your reasoning, or admission chances.</p></div>):<div className="version-history"><h3>Every revision has a place</h3><p>Submitting a changed draft creates a new snapshot. Your editor always keeps your latest text.</p>{!attempts.length&&<p>No reviews yet. Your first submission will appear here.</p>}{[...attempts].sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).map((a,i)=><details key={a.id}><summary><span><strong>Version {attempts.length-i}</strong><small>{niceDate(a.createdAt)} · {a.review.metrics.words} words</small></span><strong>{a.review.score}<small>/100</small></strong></summary><p className="snapshot-text">{a.text}</p><Button secondary onClick={()=>{onSelectReview(a.id);setTab('feedback');}}>Read this feedback <ArrowUpRight size={14}/></Button><button className="text-button" onClick={()=>download(`write-again-version-${attempts.length-i}.txt`,a.text)}><Download size={14}/> Download version</button></details>)}</div>}</aside></div></div>;
}

function ReviewPanel({attempt:a,current,previous}:{attempt:Attempt;current:boolean;previous:Attempt|null}){
 const r=a.review,delta=previous?r.score-previous.review.score:null;
 return <div className="review-content"><div className="review-label"><span className="eyebrow">AUTOMATED RUBRIC ESTIMATE</span><Pill>{r.tone==='direct'?'Direct':'Gentle'}</Pill></div>{!current&&<div className="stale-notice">This feedback describes a saved version. Review the current draft to measure your changes.</div>}<div className="score-header"><div className="score-circle"><strong>{r.score}</strong><span>/ 100</span></div><div><h2>{r.band}</h2>{delta!==null&&<span className={`delta ${delta>=0?'positive':'negative'}`}>{delta>0?'+':''}{delta} vs previous version</span>}<small>{r.metrics.words} words · {r.metrics.paragraphs} paragraphs</small></div></div><p className="review-summary">{r.summary}</p><details className="rubric-details" open><summary>The five-part rubric <span>100 points</span></summary>{r.rubric.map(row=><div className="rubric-row" key={row.label}><div><strong>{row.label}</strong><span>{row.score} / {row.max}</span></div><div className="progress-track"><span style={{width:`${row.score/row.max*100}%`}}/></div><p>{row.detail}</p></div>)}</details><div className="review-section-title"><h3>Where to improve</h3><span>{r.issues.length} observations</span></div>{r.issues.map((issue,i)=><article className={`feedback-issue ${issue.severity}`} key={`${issue.title}-${i}`}><div className="issue-kicker">{i===0?'START HERE':issue.severity==='priority'?'DEVELOP THE DRAFT':'POLISH WITH PURPOSE'}</div><h3>{issue.title}</h3><p>{issue.observation}</p>{issue.quote&&<blockquote>{issue.quote}</blockquote>}<div className="issue-action"><PencilLine size={14}/><p><strong>Your next move:</strong> {issue.action}</p></div></article>)}{r.strengths.length>0&&<section className="strengths"><h3><CheckCircle2 size={16}/> What is working</h3><ul>{r.strengths.map(s=><li key={s}>{s}</li>)}</ul></section>}<section className="human-check"><h3>Questions the score cannot answer</h3><ol>{r.questions.map(q=><li key={q}>{q}</li>)}</ol></section><div className="method-note">This score is a practice estimate from visible text patterns, not an official grade or an AI reading of meaning. A high score does not establish originality, sound reasoning, correct facts, or admissions readiness. English-language checks may flag other languages incorrectly.</div></div>;
}

function DraftList({drafts,attempts,onOpen}:{drafts:Draft[];attempts:Attempt[];onOpen:(d:Draft)=>void}){
 const [query,setQuery]=useState('');const filtered=[...drafts].sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).filter(d=>`${d.title} ${d.prompt.category} ${d.text}`.toLowerCase().includes(query.toLowerCase()));
 return <section className="draft-archive">{drafts.length>0&&<label className="search-field"><Search size={17}/><input aria-label="Search drafts" placeholder="Find a draft…" value={query} onChange={e=>setQuery(e.target.value)}/></label>}<div className="draft-grid">{filtered.map(d=>{const reviews=attempts.filter(a=>a.draftId===d.id).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));return <button className="draft-card" key={d.id} onClick={()=>onOpen(d)}><div className="section-top"><FileText size={20}/><Pill>{d.prompt.category}</Pill></div><h2>{d.title||'Untitled draft'}</h2><p>{d.text?d.text.slice(0,150):'An empty page is a beginning, too.'}</p><div className="draft-card-meta"><span>{wordsOf(d.text).length} words · {niceDate(d.updatedAt)}</span><span>{reviews.length?`${reviews.length} ${reviews.length===1?'review':'reviews'} · ${reviews[0].review.score}/100`:'Not reviewed'}<ArrowUpRight size={15}/></span></div></button>;})}</div>{drafts.length>0&&!filtered.length&&<Empty icon={Search} title="No draft matches that search" text="Try a phrase from your title or essay."/>}</section>;
}

function Progress({workspace:w,xp,streak,onOpen,onPractice}:{workspace:Workspace;xp:number;streak:number;onOpen:(a:Attempt)=>void;onPractice:()=>void}){
 const [filter,setFilter]=useState('all');const reviewedIds=[...new Set(w.attempts.map(a=>a.draftId))];const attempts=[...w.attempts].filter(a=>filter==='all'||a.draftId===filter).sort((a,b)=>a.createdAt.localeCompare(b.createdAt));
 const recent=attempts.slice(-16),last=recent.at(-1),first=recent[0];const rubricAverages=last?.review.rubric.map((r,i)=>({...r,score:Math.round(attempts.reduce((s,a)=>s+a.review.rubric[i].score,0)/attempts.length)}));
 const week=Array.from({length:7},(_,i)=>{const date=new Date();date.setDate(date.getDate()-6+i);const key=date.toLocaleDateString('en-CA');return {key,label:date.toLocaleDateString(undefined,{weekday:'short'}),count:w.attempts.filter(a=>new Date(a.createdAt).toLocaleDateString('en-CA')===key).length};});
 const badges=[{name:'First page',desc:'Write at least 80 words in a draft.',earned:w.drafts.some(d=>wordsOf(d.text).length>=80),icon:Feather},{name:'Second look',desc:'Review two versions of the same draft.',earned:reviewedIds.some(id=>w.attempts.filter(a=>a.draftId===id).length>=2),icon:PencilLine},{name:'Finding flow',desc:'Complete the four beginner lessons.',earned:lessons.filter(l=>l.stage===0).every(l=>w.completions.some(c=>c.lessonId===l.id)),icon:Leaf},{name:'Your own voice',desc:'Complete all sixteen lessons.',earned:w.completions.length===16,icon:GraduationCap}];
 return <><PageHeading kicker="SMALL STEPS LEAVE A TRAIL" title="See how far you’re coming" text="Track the practice, then read the revisions. Your progress is bigger than a score."/><div className="stats-grid"><Stat icon={PencilLine} label="Reviewed pieces" value={`${reviewedIds.length}`} note={`${w.attempts.length} total reviews, including revisions`}/><Stat icon={BookOpen} label="Lessons complete" value={`${w.completions.length}`} suffix="/ 16" note="Reading, checking, and applying"/><Stat icon={Flame} label="Practice streak" value={`${streak}`} suffix="days" note="Based on days with a saved review"/><Stat icon={Sparkles} label="Practice points" value={`${xp}`} suffix="XP" note="100 per lesson + 25 per reviewed piece"/></div><div className="progress-columns"><section className="card score-chart"><div className="section-top"><div><span className="eyebrow">YOUR DRAFTS OVER TIME</span><h2>Practice, made visible</h2></div><label className="sr-only" htmlFor="progress-draft">Compare draft</label><select id="progress-draft" value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">All reviewed pieces</option>{reviewedIds.map(id=><option value={id} key={id}>{w.drafts.find(d=>d.id===id)?.title||'Saved essay'}</option>)}</select></div>{recent.length?<><div className="chart-summary"><strong>{last?.review.score}<small>/100 latest</small></strong>{filter!=='all'&&first&&last&&recent.length>1&&<span>{last.review.score-first.review.score>=0?'+':''}{last.review.score-first.review.score} since first version</span>}</div><svg className="progress-chart" viewBox="0 0 600 230" role="img" aria-label={`Rubric estimates in chronological order: ${recent.map(a=>a.review.score).join(', ')}`}><title>Last {recent.length} rubric estimates. Range: 0 to 100.</title>{[0,25,50,75,100].map(n=><g key={n}><line x1="38" x2="580" y1={200-n*1.7} y2={200-n*1.7} stroke="#e8e9e2" strokeDasharray="4 5"/><text x="6" y={205-n*1.7} fill="#808476" fontSize="11">{n}</text></g>)}<polyline points={recent.map((a,i)=>`${recent.length===1?309:45+i*(528/Math.max(1,recent.length-1))},${200-a.review.score*1.7}`).join(' ')} fill="none" stroke="#627e4a" strokeWidth="2.5" strokeLinejoin="round"/>{recent.map((a,i)=><circle key={a.id} cx={recent.length===1?309:45+i*(528/Math.max(1,recent.length-1))} cy={200-a.review.score*1.7} r="4.5" fill="#627e4a" stroke="white" strokeWidth="2"><title>{a.title}: {a.review.score}/100, {niceDate(a.createdAt)}</title></circle>)}</svg><p className="chart-note">Last 16 reviews. Scores vary by task and length. Select one piece to compare its revisions more fairly.</p></>:<Empty icon={TrendingUp} title="Your baseline starts with one draft" text="A reviewed piece will give this graph its first point." action={<Button secondary onClick={onPractice}>Choose a prompt <ArrowRight size={14}/></Button>}/>}</section><section className="card practice-week"><span className="eyebrow">SHOWING UP COUNTS</span><h2>Your last seven days</h2><div className="week-grid">{week.map(d=><div key={d.key}><span>{d.label}</span><div className={d.count?'practiced':''} title={`${d.key}: ${d.count} reviews`}>{d.count?<Check size={19}/>:<span/>}</div><small>{d.count||'—'}</small></div>)}</div><p>A practice day means you saved at least one review. There’s no penalty for a missed day.</p><div className="week-note"><Leaf size={19}/><span>Consistency grows from a return,<br/>not a perfect streak.</span></div></section></div><div className="progress-columns"><section className="card"><span className="eyebrow">A MORE USEFUL KIND OF SCORE</span><h2>Your rubric signals</h2>{rubricAverages?<>{rubricAverages.map(r=><div className="skill-bar" key={r.label}><div><span>{r.label}</span><strong>{r.score}/20</strong></div><div className="progress-track"><span style={{width:`${r.score/20*100}%`}}/></div></div>)}<p className="small-text muted">Average of the selected reviews. These measure text patterns, not certified writing proficiency.</p></>:<p className="muted">Your first review will show the five areas you can practice.</p>}</section><section className="card"><span className="eyebrow">MILESTONES, NOT DEADLINES</span><h2>Little reasons to keep going</h2><div className="badge-list">{badges.map(({name,desc,earned,icon:Icon})=><div className={earned?'earned':''} key={name}><span><Icon size={22}/></span><div><strong>{name}</strong><p>{desc}</p></div>{earned?<CheckCircle2 size={17}/>:<LockKeyhole size={15}/>}</div>)}</div></section></div>{attempts.length>0&&<section className="card review-log"><div className="section-top"><div><span className="eyebrow">THE WORK BEHIND THE NUMBERS</span><h2>Your review history</h2></div><span className="muted">{attempts.length} reviews</span></div>{[...attempts].reverse().slice(0,30).map(a=><button key={a.id} onClick={()=>onOpen(a)}><span className="log-icon"><FileText size={18}/></span><span><strong>{a.title}</strong><small>{niceDate(a.createdAt)} · {a.review.metrics.words} words · {a.prompt.category}</small></span><span className="log-score">{a.review.score}<small>/100</small></span><ArrowUpRight size={16}/></button>)}</section>}</>;
}

function Settings({workspace:w,onUpdate,onExport,onNotify}:{workspace:Workspace;onUpdate:(fn:(s:Workspace)=>Workspace)=>void;onExport:()=>void;onNotify:(text:string)=>void}){
 const [importError,setImportError]=useState('');const fileRef=useRef<HTMLInputElement>(null);
 async function importBackup(file?:File){if(!file)return;setImportError('');try{if(file.size>1800000)throw new Error('Choose a Write Again backup smaller than 1.8 MB.');const data=safeBackup(JSON.parse(await file.text()));const {mergeWorkspace}=await import('@/lib/workspace');onUpdate(s=>mergeWorkspace(s,data));onNotify('Backup merged. Existing work was preserved.');}catch(e){setImportError(e instanceof Error&&e.message.length<200?e.message:'This is not a valid Write Again backup. Your existing work is unchanged.');}finally{if(fileRef.current)fileRef.current.value='';}}
 return <><PageHeading kicker="MAKE THIS SPACE WORK FOR YOU" title="Your studio, your pace" text="Choose how you practice and keep a copy of the work you care about."/><div className="settings-grid"><section className="card"><span className="eyebrow">HOW THE COACH SPEAKS</span><h2>Feedback tone</h2><p className="muted">The rubric and score stay the same. The delivery changes. Criticism targets the work.</p>{([{value:'direct',title:'Direct & demanding',text:'Clear criticism. No decorative praise. Start with what most needs work.'},{value:'gentle',title:'Calm & constructive',text:'The same observations, phrased with a little more breathing room.'}] as const).map(o=><label className={`setting-choice ${w.settings.tone===o.value?'selected':''}`} key={o.value}><input type="radio" name="tone" value={o.value} checked={w.settings.tone===o.value} onChange={()=>onUpdate(s=>({...s,settings:{...s.settings,tone:o.value},settingsUpdatedAt:stamp()}))}/><span><strong>{o.title}</strong><small>{o.text}</small></span></label>)}<label className="daily-goal" htmlFor="daily-goal">Default focus session <select id="daily-goal" value={w.settings.dailyMinutes} onChange={e=>onUpdate(s=>({...s,settings:{...s.settings,dailyMinutes:Number(e.target.value)},settingsUpdatedAt:stamp()}))}>{[5,10,15,20,25,30,45,60].map(n=><option value={n} key={n}>{n} minutes</option>)}</select></label><p className="small-text muted">The writing timer starts with the shorter of your default and the prompt’s suggested duration. You can change it in the editor.</p></section><section className="card"><span className="eyebrow">YOUR WORDS BELONG TO YOU</span><h2>Keep a backup</h2><p className="muted">This studio saves drafts, reviews, and lesson progress in your browser. Export a backup before clearing browsing data or moving to another device, then import it in your other browser.</p><div className="backup-actions"><Button onClick={onExport}><Download size={16}/> Export all my work</Button><Button secondary onClick={()=>fileRef.current?.click()}><Upload size={16}/> Import a backup</Button></div><input type="file" className="sr-only" aria-label="Import Write Again backup" accept="application/json,.json" ref={fileRef} onChange={e=>importBackup(e.target.files?.[0])}/>{importError&&<p className="check-wrong" role="alert">{importError}</p>}<p className="small-text muted">Export includes your complete essays, review snapshots, notes, and progress in a JSON file. Import merges by record and keeps the newer version; it does not erase your archive.</p><div className="data-count"><strong>{w.drafts.length} drafts</strong><strong>{w.attempts.length} reviews</strong><strong>{w.completions.length} completed lessons</strong></div></section><section className="card settings-method"><FeedbackGuide/></section></div></>;
}

function Modal({title,children,onClose}:{title:string;children:React.ReactNode;onClose:()=>void}){
 const ref=useRef<HTMLDialogElement>(null);
 useEffect(()=>{const dialog=ref.current;dialog?.showModal();return()=>dialog?.close();},[]);
 return <dialog ref={ref} className="modal" onCancel={e=>{e.preventDefault();onClose();}} onClick={e=>{if(e.target===e.currentTarget)onClose();}} aria-labelledby="modal-heading"><div className="modal-header"><h2 id="modal-heading">{title}</h2><IconButton icon={X} label="Close dialog" onClick={onClose}/></div><div className="modal-content">{children}</div></dialog>;
}
function CustomPrompt({onStart}:{onStart:(p:Prompt)=>void}){
 const [title,setTitle]=useState(''),[question,setQuestion]=useState(''),[level,setLevel]=useState(2),[min,setMin]=useState(200),[max,setMax]=useState(500),[kind,setKind]=useState<'personal'|'argument'|'micro'>('personal');
 const valid=!!title.trim()&&question.trim().length>=10&&min>=20&&max>=min&&max<=5000;
 return <form className="custom-prompt" onSubmit={e=>{e.preventDefault();if(valid)onStart({id:`custom-${uid()}`,title:title.trim(),question:question.trim(),category:kind==='argument'?'Argument & ethics':'Personal growth',level,minWords:min,maxWords:max,minutes:[8,15,25,35][level-1],kind,hints:['Answer the exact task you set.','Develop a particular example.','Explain why your example matters.']});}}><p>Bring an admissions question, a school assignment, or a topic you want to explore. Paste your essay in the studio after creating the draft.</p><label>Title<input required maxLength={500} value={title} onChange={e=>setTitle(e.target.value)} placeholder="What I want to write about"/></label><label>The question or task<textarea required minLength={10} maxLength={3000} rows={4} value={question} onChange={e=>setQuestion(e.target.value)} placeholder="What should this essay explore or answer?"/></label><div className="form-two"><label>Practice level<select value={level} onChange={e=>setLevel(Number(e.target.value))}>{stages.map((s,i)=><option value={i+1} key={s.name}>{s.level}</option>)}</select></label><label>Essay style<select value={kind} onChange={e=>setKind(e.target.value as typeof kind)}><option value="personal">Personal / reflective</option><option value="argument">Argument / academic</option><option value="micro">Short paragraph</option></select></label></div><div className="form-two"><label>Minimum words<input required type="number" min={20} max={5000} value={min} onChange={e=>setMin(Number(e.target.value))}/></label><label>Maximum words<input required type="number" min={min} max={5000} value={max} onChange={e=>setMax(Number(e.target.value))}/></label></div>{max<min&&<p className="check-wrong">The maximum must be at least the minimum.</p>}<button className="button full-width" disabled={!valid} type="submit">Open my writing page <ArrowRight size={16}/></button></form>;
}
function Warmup({onSave,storageKey}:{onSave:(text:string,title:string)=>void;storageKey:string}){
 const [selected,setSelected]=useState(0),[text,setText]=useState('');const prompt=warmups[selected];
 useEffect(()=>{try{setText(sessionStorage.getItem(storageKey)||'');}catch{}},[]);
 function write(value:string){setText(value);try{sessionStorage.setItem(storageKey,value);}catch{}}
 return <div className="warmup"><p>For now, the goal is to keep going. No grade. No perfect opening.</p><label htmlFor="warmup-choice">Choose a starting point</label><select id="warmup-choice" value={selected} onChange={e=>setSelected(Number(e.target.value))}>{warmups.map((p,i)=><option key={p.title} value={i}>{p.title}</option>)}</select><div className="warmup-prompt"><h3>{prompt.start}</h3><p>{prompt.task}</p></div><Countdown minutes={5}/><label className="sr-only" htmlFor="warmup-text">Your freewrite</label><textarea id="warmup-text" rows={10} maxLength={60000} value={text} onChange={e=>write(e.target.value)} placeholder={prompt.start}/><div className="warmup-bottom"><small>{wordsOf(text).length} words · Backed up in this tab</small><Button disabled={!text.trim()} onClick={()=>{onSave(text,prompt.title);try{sessionStorage.removeItem(storageKey);}catch{}}}>Save as a draft <ArrowRight size={15}/></Button></div></div>;
}
function FeedbackGuide({onClose}:{onClose?:()=>void}){
 return <div className="feedback-guide"><span className="eyebrow">HONEST ABOUT THE WORK. HONEST ABOUT THE TOOL.</span><h2>A second look, with a clear rubric</h2><p>The built-in reviewer analyzes your English draft using visible text patterns. It needs no external account or paid API. Direct mode is candid about weaknesses and gives an action you can try.</p><div className="guide-grid"><div><h3>It can help you inspect</h3><ul><li>The word target and paragraph development.</li><li>Overloaded sentences, repetition, and filler.</li><li>Example, explanation, and qualification cues.</li><li>Common editing patterns and vague openings.</li></ul></div><div><h3>It cannot reliably judge</h3><ul><li>Whether the argument is logical or original.</li><li>Whether examples or facts are accurate.</li><li>Full grammar correctness or narrative depth.</li><li>Your admission chances or official essay grade.</li></ul></div></div><p><strong>Read a score as a practice signal.</strong> Five categories contribute up to 20 points each. The score uses the same rules across feedback tones. A keyword or transition does not earn credit for its meaning; its presence is only a cue to inspect.</p><p><strong>Use the revision loop:</strong> write, review, choose one high-impact change, revise, and review again. Use saved versions and a revision note to judge whether the change helped a reader. For your final admissions essay, seek a trusted human reader too.</p>{onClose&&<Button className="full-width" onClick={onClose}>I’m ready to write <PencilLine size={15}/></Button>}</div>;
}
